<?php require_once __DIR__.'/auth.php';api_auth();header('Content-Type: application/json');$root=realpath(__DIR__.'/..');$out=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root));foreach($it as $file){if(!$file->isFile()||!preg_match('/\.(jpe?g|png|webp|gif)$/i',$file->getFilename()))continue;$rel=str_replace('\\','/',substr($file->getPathname(),strlen($root)+1));if(str_starts_with($rel,'backend/'))continue;$size=$file->getSize();$dim=@getimagesize($file->getPathname());$out[]=['path'=>$rel,'label'=>pathinfo($rel,PATHINFO_FILENAME),'group'=>dirname($rel),'exists'=>true,'bytes'=>$size,'width'=>$dim[0]??0,'height'=>$dim[1]??0,'used'=>true,'pages'=>[]];}echo json_encode($out,JSON_UNESCAPED_SLASHES);
